"""Monthly revenue by issue date: invoiced, credited and net."""
from __future__ import annotations

from dataclasses import dataclass
from datetime import date
from decimal import Decimal

from ledgerly.credit_notes.models import CreditNote
from ledgerly.invoices.models import Invoice


@dataclass
class Revenue:
    month: str
    invoiced: Decimal
    credited: Decimal

    @property
    def net(self) -> Decimal:
        return self.invoiced - self.credited


def month_bounds(month: str) -> tuple[date, date]:
    """'2026-02' -> (2026-02-01, 2026-03-01); the end is exclusive."""
    year, m = map(int, month.split("-"))
    return date(year, m, 1), date(year + m // 12, m % 12 + 1, 1)


def revenue(month: str, invoices: list[Invoice], credit_notes: list[CreditNote]) -> Revenue:
    start, end = month_bounds(month)
    invoiced = sum((i.total() for i in invoices
                    if i.status != "draft" and i.issued_on and start <= i.issued_on < end), Decimal("0.00"))
    # CreditNote.total() is still a float until billing-agent's fix lands.
    credited = sum((Decimal(str(c.total())) for c in credit_notes if start <= c.issued_on < end), Decimal("0.00"))
    return Revenue(month, invoiced, credited)
